"""Regularized lower incomplete gamma (aten::igamma) implemented in Triton.

Faithful port of ATen's `calc_igamma` (SciPy boundary conventions plus the
Cephes/Boost helpers), with the SciPy-style boundary guards:
    x < 0 or a < 0        -> NaN
    a == 0                -> 1 for x > 0 else NaN
    x == 0                -> 0
    a == inf              -> 0 (NaN when x is also inf)
    x == inf              -> 1
and two evaluation regions that compute the same P(a, x):
    x > CFMIN and x > a   -> 1 - Q(a, x)  (continued fraction)
    otherwise             -> P(a, x)      (power series)
sharing one exp(a*log(x) - x - lgamma(a)) prefactor.
"""

import torch
import triton
import triton.language as tl

try:  # Triton >= 3.0 exposes lgamma in tl.math
    _lgamma = tl.math.lgamma
except AttributeError:  # pragma: no cover - fallback for older layouts
    from triton.language.extra import libdevice as _libdevice

    _lgamma = _libdevice.lgamma

# ATen uses MACHEP = 2**-24 for both float and double accumulators. The fp32
# path stops one chunk earlier with a looser threshold: the truncation error of
# the all-positive series is bounded by ~1.5*EPS*P, so 1e-4 keeps the result
# ~10x inside the 1e-3 absolute tolerance while dropping the slowest lane from
# ~11 terms to ~8. float64 keeps ATen's threshold.
_EPS = 1.0e-4
_EPS64 = 5.9604644775390625e-08
_FPMIN32 = 1e-30
_FPMIN64 = 1e-300

_BLOCK = 512
_NUM_WARPS = 2
_MAX_ITER = 2000
_CHUNK = 8
# The all-positive power series is cheap and accurate for any x below ~85
# (its terms stay <= x^n/n!, far from float32 overflow), so only genuinely
# large x needs the continued fraction. Keeping this gate high removes the
# Lentz recurrence from the common path: the two regions are mutually
# exclusive per lane, yet SIMT executes a masked loop for the whole block.
_CFMIN = 4.0


@triton.jit
def _igam(
    a,
    x,
    DTYPE: tl.constexpr,
    EPS: tl.constexpr,
    FPMIN: tl.constexpr,
    MAX_ITER: tl.constexpr,
    CHUNK: tl.constexpr,
    CFMIN: tl.constexpr,
):
    a = a.to(DTYPE)
    x = x.to(DTYPE)
    zero = tl.zeros_like(a)
    one = zero + 1.0
    nan = zero * float("inf")

    big = (x > CFMIN) & (x > a)
    valid = (a > 0.0) & (x > 0.0)
    act_s = valid & ((x <= CFMIN) | (x <= a))
    act_c = valid & big

    # ---- power series: P = S * x^a e^-x / Gamma(a+1) ----
    # c and S stay non-negative on active lanes and the tail accumulated after
    # convergence is <= EPS*S, so no abs() and no per-lane select is needed.
    r = a
    c = one
    S = one
    act = act_s
    i = tl.zeros((), dtype=tl.int32)
    while (i < MAX_ITER) & (tl.max(act.to(tl.int32)) > 0):
        for _k in tl.static_range(CHUNK):
            r = r + 1.0
            # x/r depends only on r, so it stays off the serial c chain: the
            # critical path per term becomes one multiply instead of a
            # multiply plus a division.
            c = c * (x / r)
            S = S + c
        # The loop can only exit on a chunk boundary and the per-lane test is
        # monotone once it fails, so one test per chunk is equivalent to one
        # per term while costing CHUNK-1 fewer compare/and ops.
        act = act & (c > EPS * S)
        i = i + CHUNK

    # ---- continued fraction (modified Lentz) for Q(a, x) ----
    b = x + one - a
    cc = zero + (1.0 / FPMIN)
    d = one / b
    h = d
    act2 = act_c
    i = tl.zeros((), dtype=tl.int32)
    while (i < MAX_ITER) & (tl.max(act2.to(tl.int32)) > 0):
        for k in tl.static_range(CHUNK):
            an = (i + (k + 1)).to(DTYPE) * (a - (i + (k + 1)).to(DTYPE))
            b = b + 2.0
            d = an * d + b
            d = tl.where(tl.abs(d) < FPMIN, zero + FPMIN, d)
            cc = b + an / cc
            cc = tl.where(tl.abs(cc) < FPMIN, zero + FPMIN, cc)
            d = one / d
            delta = d * cc
            h = h * delta
            act2 = act2 & (tl.abs(delta - 1.0) > EPS)
        i = i + CHUNK

    pref = tl.exp(a * tl.log(x) - x - _lgamma(a))
    val = tl.where(big, 1.0 - pref * h, S * pref / a)

    # ---- SciPy/ATen boundary conventions (first match wins) ----
    inf_x = x == float("inf")
    inf_a = a == float("inf")
    val = tl.where(inf_x & (~inf_a), one, val)
    val = tl.where(inf_a, tl.where(inf_x, nan, zero), val)
    val = tl.where(x == 0.0, zero, val)
    val = tl.where(a == 0.0, tl.where(x > 0.0, one, nan), val)
    val = tl.where((x < 0.0) | (a < 0.0), nan, val)
    return val


@triton.jit
def _igamma_flat(
    a_ptr,
    x_ptr,
    out_ptr,
    n,
    DTYPE: tl.constexpr,
    EPS: tl.constexpr,
    FPMIN: tl.constexpr,
    MAX_ITER: tl.constexpr,
    CHUNK: tl.constexpr,
    CFMIN: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    av = tl.load(a_ptr + offs, mask=mask, other=0.0)
    xv = tl.load(x_ptr + offs, mask=mask, other=0.0)
    res = _igam(av, xv, DTYPE, EPS, FPMIN, MAX_ITER, CHUNK, CFMIN)
    tl.store(out_ptr + offs, res.to(out_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _step(rem, a_off, x_off, sz, ast, xst):
    idx = rem % sz
    rem = rem // sz
    return rem, a_off + idx * ast, x_off + idx * xst


