            a,
            x,
            out,
            n,
            sz[0],
            sz[1],
            sz[2],
            sz[3],
            sz[4],
            sz[5],
            sz[6],
            sz[7],
            ast[0],
            ast[1],
            ast[2],
            ast[3],
            ast[4],
            ast[5],
            ast[6],
            ast[7],
